int main(){api::EngineRequestContext c;c.database_path=(std::filesystem::temp_directory_path()/std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())).string();c.database_uuid.canonical="019d0000-0000-7000-8000-000000002375";c.security_context_present=true;c.trace_tags={"right:SBLR_EXECUTOR_AVAILABILITY_ADMIN"};api::SblrExecutorAvailabilityRowIdentity r;r.executor_id=api::kSblrReservationReleaseExecutorId;r.opcode_code=api::kSblrReservationReleaseOpcodeCode;r.opcode_version=api::kSblrReservationReleaseOpcodeVersion;r.operand_descriptor_id=api::kSblrReservationReleaseOperandDescriptorId;r.result_descriptor_id=api::kSblrReservationReleaseResultDescriptorId;r.result_descriptor_version=1;auto loaded=api::LoadSblrExecutorAvailabilitySnapshot(c,r);assert(loaded.ok&&loaded.snapshot.installed);api::SblrExecutorAvailabilitySetRequest q;q.database_uuid=c.database_uuid.canonical;q.expected_snapshot_uuid=loaded.snapshot.snapshot_uuid;q.expected_generation=loaded.snapshot.generation;q.exact_row_identity=r;q.requested_state=api::SblrExecutorAvailabilityState::revoked;q.reason_code="CSC-TEST-002375";assert(api::SetSblrExecutorAvailability(c,q).ok);api::SblrExecutorAvailabilitySnapshot current;assert(api::RevalidateSblrExecutorAvailability(c,r,loaded.snapshot,&current).code=="SBLR.OPCODE.EXECUTOR_EVIDENCE_MISSING");std::error_code ec;std::filesystem::remove(c.database_path+".sb.sblr_executor_availability_registry.v1.transaction_reservation_release",ec);}
